   public static final void buildMCTable() {
      typeDataTable = new TypeData[256];

      for(int i = 0; i < 256; ++i) {
         int typeIndex = 0;

         for(int j = 0; j < 8; ++j) {
            typeIndex <<= 1;
            if (BASETABLE[i][j] == 1) {
               typeIndex |= 1;
            }
         }

         typeDataTable[typeIndex] = new TypeData();
         typeDataTable[typeIndex].typeIndex = typeIndex;
         typeDataTable[typeIndex].trianglesNum = BASETABLE[i][8];
         int[][] vertices = new int[5][];

         int x;
         for(x = 0; x < 5; ++x) {
            vertices[x] = new int[3];
         }

         x = 9;

         for(int y = 0; x < 24; ++y) {
            vertices[y / 3][y % 3] = BASETABLE[i][x];
            ++x;
         }

         typeDataTable[typeIndex].edgeVertices = vertices;
      }

   }

